"""Build ``sample_rules.rwz``: a hand-built, fully synthetic Outlook rules export.

The bundled test fixture is generated by this script -- it is NOT a real export.
Every address, name, folder and subject below is invented (``example.com``,
``example.org`` and ``.invalid`` domains only), and every identifier field is
zero-filled, so the file carries no mailbox, tenant or Exchange object data.

The real ``.rwz`` format is an undocumented MAPI blob. This script does not try to
reproduce it byte-for-byte; it emits only the structures that
``rwz_importer.parser.rwz_parser`` actually reads (see that module's docstring),
surrounded by zero padding:

* file header: a small version/count prelude plus the owner's address as a
  single-byte ``SMTP:`` string (the parser discovers owner candidates from the
  single-byte view of the file);
* per rule: ``14 00 <len> <utf16 name>`` (rule-name anchor), then its conditions,
  then ``<owner utf16> 00 00 00 00 <len> <utf16 folder>`` (move-to-folder action);
* a sender either as a MAPI one-off entry ID (public one-off provider UID, then
  ``display\\0 SMTP\\0 address\\0`` in UTF-16LE -- the parser keys on ``SMTP\\0``) or,
  to exercise the X.500 fallback, as an Exchange address-book entry ID (public
  provider UID + an invented, zero-GUID X.500 DN) followed by a one-byte tag and
  the UTF-16LE address, which the parser sees as a "glued capital" junk prefix;
* a subject-contains list: ``01 80 cd 00 00 00 <count:u32> 00 00 00 00`` then
  ``<len:u8> <utf16 keyword>`` entries separated by null padding.

Run ``python tests/fixtures/make_sample_rwz.py`` to (re)write the fixture next to
this file; ``tests/test_fixture_generator.py`` checks the committed file matches.
"""

from __future__ import annotations

import struct
import sys
from pathlib import Path

OWNER = "alice.sample@example.com"

# Public MAPI constants (not tenant-bound): the one-off entry ID provider UID and
# the Exchange address-book provider UID (muidEMSAB).
ONE_OFF_UID = bytes.fromhex("812b1fa4bea310199d6e00dd010f5402")
EMSAB_UID = bytes.fromhex("dca740c8c042101ab4b908002b2fe182")

SUBJECT_MARKER = bytes.fromhex("0180cd000000")

# (name, folder, senders, subjects). A sender is (address, display, kind) where
# kind is "smtp" (one-off entry ID) or "x500" (Exchange DN + UTF-16 address).
RULES: list[tuple[str, str, list[tuple[str, str, str]], list[str]]] = [
    ("Meeting Invites", "Meeting Invites", [], ["Accepted: ", "Tentative: ", "Aceite: "]),
    ("SI HelpDesk", "SI HelpDesk", [("helpdesk@example.com", "", "x500")], []),
    ("Confluence", "Confluence", [("confluence-noreply@example.com", "", "x500")], []),
    (
        "Email LabOps",
        "Email LabOps",
        [("alice.sample@example.org", "alice.sample@example.org", "smtp")],
        [],
    ),
    ("ACMESUP", "ACMESUP", [], ["Acmepharm", "ACMEPHA"]),
    ("PRJX", "PRJX – Project Phoenix", [], ["PRJX"]),
    (
        "org daily stuff",
        "Org News",
        [("noreply@social.example.com", "noreply@social.example.com", "smtp")],
        [],
    ),
    (
        "Bitbucket",
        "Bitbucket",
        [("bitbucket-noreply@example.com", "bitbucket-noreply@example.com", "smtp")],
        [],
    ),
    ("Report", "Report", [("report-mail@example.com", "report-mail@example.com", "smtp")], []),
    (
        "Sharepoint",
        "Sharepoint",
        [("no-reply@docs.example.com", "no-reply@docs.example.com", "smtp")],
        [],
    ),
    ("Training", "Training", [("training@example.com", "training@example.com", "smtp")], []),
    ("Teams", "Teams", [("no-reply@chat.example.com", "no-reply@chat.example.com", "smtp")], []),
    (
        "Weekly Digest",
        "Weekly Digest",
        [
            ("digest-noreply@engage.mail.invalid", "digest-noreply@engage.mail.invalid", "smtp"),
            ("digest-notify@engage.mail.invalid", "Viva Engage", "smtp"),
        ],
        [],
    ),
]


def u16(s: str) -> bytes:
    return s.encode("utf-16-le")


def u16z(s: str) -> bytes:
    return u16(s) + b"\x00\x00"


def _counted(s: str) -> bytes:
    n = len(s)
    if not 1 <= n <= 60:
        raise ValueError(f"string too long for a u8 length prefix: {s!r}")
    return bytes([n]) + u16(s)


def _smtp_sender(address: str, display: str) -> bytes:
    # MAPI one-off entry ID: flags(4) + provider UID + version(2) + flags(2) + strings.
    body = b"\x00" * 4 + ONE_OFF_UID + b"\x00\x00" + struct.pack("<H", 0x8001)
    body += u16z(display or address) + u16z("SMTP") + u16z(address)
    return struct.pack("<I", len(body)) + body + b"\x00" * 4


def _x500_sender(address: str) -> bytes:
    local = address.split("@", 1)[0]
    dn = (
        "/o=ExampleOrg/ou=Exchange Administrative Group (FYDIBOHF23SPDLT)"
        f"/cn=Recipients/cn={'0' * 32}-{local}"
    )
    body = b"\x00" * 4 + EMSAB_UID + struct.pack("<II", 1, 0) + dn.encode("ascii") + b"\x00"
    # A one-byte record tag ('K') then the UTF-16 address; the parser reads the tag
    # as a glued-on capital and strips it (see _clean_x500_email).
    return struct.pack("<I", len(body)) + body + b"\x00" + b"K\x00" + u16z(address) + b"\x00" * 4


def _subjects(keywords: list[str]) -> bytes:
    out = SUBJECT_MARKER + struct.pack("<I", len(keywords)) + b"\x00" * 4
    for kw in keywords:
        out += _counted(kw) + b"\x00\x00"
    return out + b"\x00" * 4


def build() -> bytes:
    out = bytearray()
    out += struct.pack("<II", 1, len(RULES))
    out += b"\x00" * 8
    out += b"SMTP:" + OWNER.encode("ascii") + b"\x00"
    out += b"\x00" * (-len(out) % 4)
    for idx, (name, folder, senders, subjects) in enumerate(RULES, start=1):
        out += struct.pack("<I", idx) + b"\x00" * 16  # rule index + zeroed rule id
        out += b"\x14\x00" + _counted(name) + b"\x00\x00"
        for address, display, kind in senders:
            out += _smtp_sender(address, display) if kind == "smtp" else _x500_sender(address)
        if subjects:
            out += _subjects(subjects)
        # Move-to-folder action: owner store marker, then the counted folder name.
        out += b"\x00" * 16  # zeroed store/folder entry id
        out += u16(OWNER) + b"\x00" * 4 + bytes([len(folder)]) + u16(folder)
        out += b"\x00" * 8
        out += b"\x00" * (-len(out) % 4)
    return bytes(out)


def main(argv: list[str]) -> int:
    target = Path(argv[1]) if len(argv) > 1 else Path(__file__).with_name("sample_rules.rwz")
    target.write_bytes(build())
    print(f"wrote {target} ({target.stat().st_size} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
